//! AAN initial All Guidelines view and explicitly linked Neurology publisher terminals.
use super::{common,Adapter,PlanRow};use crate::guidelines::{doc::{Block,BlockKind,GuidelineDoc},fetch::{Fetched,Fetcher},html::{blocks_from_html,sel,text_of},registry::SourceEntry};use anyhow::{bail,Context,Result};use scraper::Html;use serde_json::{json,Value};use std::collections::HashSet;use url::Url;
pub struct Aan;

// AAN serves a closed global login dialog on public pages. Accept only the exact
// observed AAN document roots, while retaining Fetcher robots/pacing and rejecting real gates.
async fn aan_public(f:&Fetcher,url:&str,kind:&str)->Result<Fetched>{
 let p=f.get(url).await?;if p.record.status!=200||!p.is_html(){bail!("AAN non-HTML or HTTP {}",p.record.status)}
 let final_url=Url::parse(&p.record.final_url)?;if final_url.host_str()!=Some("www.aan.com"){bail!("AAN public page redirected off source")}
 let html=p.text();let d=Html::parse_document(&html);if d.select(&sel("dialog#loginDialog[open]")).next().is_some(){bail!("AAN sign-in dialog is open")}
 let selector=match kind{"home"=>"main","list"=>"main #guideline-list","detail"=>"main article.article-details-page",_=>bail!("Unknown AAN page kind")};
 let root=d.select(&sel(selector)).next().context("AAN expected public root missing")?;let text=text_of(&root).to_lowercase();
 if root.select(&sel("input[type=password], form[action*=login]")).next().is_some()||text.contains("performing security verification")||text.contains("sign in to continue")||text.contains("subscribe to read"){bail!("AAN public content is gated or challenged")}
 match kind{"home" if !text.contains("guidelines")=>bail!("AAN home content missing"),"list" if !html.contains("/guidelines/home/GetListOfGuidelines?page=")=>bail!("AAN observed listing script missing"),"detail" if root.select(&sel("h1")).next().is_none()=>bail!("AAN detail title missing"),_=>{}}
 drop(d);Ok(p)
}
fn catalog(html:&str,base:&Url)->Result<Vec<(String,String)>>{let lower=html.to_lowercase();if lower.contains("performing security verification")||lower.contains("sign in to continue")||lower.contains("type=\"password\""){bail!("AAN listing batch is gated or challenged")}let d=Html::parse_document(html);let mut seen=HashSet::new();let mut v=vec![];for a in d.select(&sel("li.paginated-guideline > strong > a[href]")){let Some(u)=common::link(base,a.value().attr("href").unwrap_or(""))else{continue};if !u.to_lowercase().contains("/guidelinedetail/"){continue}let t=text_of(&a);if !t.is_empty()&&seen.insert(u.clone()){v.push((u,t));}}Ok(v)}
fn article_link(html:&str,base:&Url)->Option<String>{let d=Html::parse_document(html);let found=d.select(&sel("a[href]")).find(|a|text_of(a)=="Read Published Article").and_then(|a|common::link(base,a.value().attr("href")?));found}
fn detail_assets(html:&str,base:&Url)->Vec<Value>{let d=Html::parse_document(html);let mut seen=HashSet::new();let found=d.select(&sel("main article a[href]")).filter_map(|a|{let u=common::link(base,a.value().attr("href")?)?;let t=text_of(&a);(!t.is_empty()&&seen.insert(u.clone())).then_some(json!({"url":u,"label":t,"role":"source_linked_detail_asset","rights":"unknown"}))}).collect();found}
fn content(html:&str,base:&Url)->Result<(String,Vec<Block>,Vec<Value>,Vec<String>)>{let d=Html::parse_document(html);let root=d.select(&sel("main article")).next().context("AAN publisher article root missing")?;let t=text_of(&root);let l=t.to_lowercase();if l.contains("performing security verification")||l.contains("sign in to continue")||root.select(&sel("input[type=password]")).next().is_some(){bail!("AAN publisher gate or challenge")}if !t.contains("Practice Recommendations")||!t.contains("Analytic Process"){bail!("AAN publisher clinical template not established")}let title=root.select(&sel("h1")).next().map(|x|text_of(&x)).context("AAN publisher title missing")?;let(mut blocks,mut warnings)=blocks_from_html(&root.html(),Some(base),Some("article"));
 // Only statements explicitly prefixed with a recommendation label are classified. Rationale headings stay prose context.
 let re=regex::Regex::new(r"^([0-9]+[A-Z]?)\.\s").unwrap();let heading=regex::Regex::new(r"^Recommendation\s+[0-9]+\s+Statements?$").unwrap();for b in &mut blocks{if matches!(b.kind,BlockKind::Paragraph|BlockKind::ListItem)&&b.heading_path.iter().any(|h|heading.is_match(h)){if let Some(c)=re.captures(&b.text){let level=["Level A","Level B","Level C"].iter().find(|x|b.text.contains(**x)).map(|x|x.to_string());b.kind=BlockKind::Recommendation{label:Some(c[1].into()),strength:level,certainty:None,population:None,grading_system:None,qualifier:None};}}}
 let mut assets=vec![];let mut seen=HashSet::new();for a in root.select(&sel("a[href]")){let Some(u)=common::link(base,a.value().attr("href").unwrap_or(""))else{continue};if (u.to_lowercase().ends_with(".pdf")||u.contains("/doi/suppl/"))&&seen.insert(u.clone()){assets.push(json!({"url":u,"label":text_of(&a),"role":"publisher_asset","rights":"unknown"}));}}warnings.push("Only the observed Neurology article template is mapped; recommendation-level markup and grades require source comparison. Clinician summaries, eAppendices and companion reviews are separate assets; All Guidelines AJAX batches stop on the source-emitted load-control terminal marker; this is not proof of corpus completeness. Retired, endorsed and translated views remain separate and unreconciled.".into());Ok((title,blocks,assets,warnings))}
fn unresolved(src:&SourceEntry,u:String,t:String,e:String)->PlanRow{PlanRow{source_id:src.id.clone(),doc_key:format!("{}-unresolved",common::short_hash(&u)),url:u,title:Some(t),rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for Aan{
 async fn discover(&self,src:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{
  if limit==Some(0){return Ok(vec![])}let home=aan_public(f,src.catalog_url.as_deref().context("AAN catalog missing")?,"home").await?;let b=Url::parse(&home.record.final_url)?;
  let list={let d=Html::parse_document(&home.text());let found=d.select(&sel("a[href]")).find(|a|text_of(a)=="View All"&&a.value().attr("href").is_some_and(|x|x.to_lowercase().contains("allguidelines"))).and_then(|a|common::link(&b,a.value().attr("href")?));found.context("AAN all-guidelines link missing")?};
  let p=aan_public(f,&list,"list").await?;let pb=Url::parse(&p.record.final_url)?;let mut rows=vec![];let mut seen=HashSet::new();let mut ended=false;
  for page in 0..100 {let batch_url=pb.join(&format!("/guidelines/home/GetListOfGuidelines?page={page}"))?;let batch=f.get_ok(batch_url.as_str()).await?;let body=batch.text();let terminal=body.contains("document.querySelector(\"#load\").style.display = \"none\"");let batch_items=catalog(&body,&batch_url)?;if batch_items.is_empty(){if page>0&&terminal{ended=true;break}bail!("AAN initial or unmarked AJAX batch empty or unrecognized")}let short_batch=batch_items.len()<10;let mut new_count=0;
   for(u,t)in batch_items {if !seen.insert(u.clone()){continue}new_count+=1;let detail=match aan_public(f,&u,"detail").await{Ok(q)=>q,Err(e)=>{rows.push(unresolved(src,u,t,format!("{e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let db=Url::parse(&detail.record.final_url)?;
    if detail.text().to_lowercase().contains("this guideline is retired"){rows.push(unresolved(src,u,t,"Source explicitly labels guideline retired; status/date mapping requires dedicated template".into()));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}
    let assets=detail_assets(&detail.text(),&db);let Some(target)=article_link(&detail.text(),&db)else{rows.push(unresolved(src,u,t,"No source-labelled published article".into()));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue};
    match f.get_ok(&target).await{Ok(q)=>{let qb=Url::parse(&q.record.final_url)?;match content(&q.text(),&qb){Ok((title,_,_,_))=>{let k=common::short_hash(&u);rows.push(PlanRow{source_id:src.id.clone(),doc_key:format!("{}-{}",k,&q.record.sha256[..12]),url:target,title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"work_key":k,"sha256":q.record.sha256,"detail_url":u,"detail_assets":assets})})},Err(e)=>rows.push(unresolved(src,u,t,format!("Linked publisher template unresolved: {e:#}")))}}Err(e)=>rows.push(unresolved(src,u,t,format!("Linked publisher inaccessible: {e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}
   }if new_count==0{bail!("AAN AJAX batch repeated previously seen guideline IDs")}if terminal{ended=true;break}if short_batch{rows.push(unresolved(src,batch_url.to_string(),"AAN catalog batch".into(),"Short AJAX batch without observed terminal marker; enumeration incomplete".into()));return Ok(rows)}
  }if !ended{bail!("AAN AJAX pagination exceeded safety bound without an observed empty batch")}Ok(rows)
 }
 async fn extract(&self,src:&SourceEntry,f:&Fetcher,row:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=row.extra["discovery_error"].as_str(){bail!("AAN terminal unresolved: {e}")}let p=f.get_ok(&row.url).await?;if row.extra["sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("AAN article changed after discovery")}let base=Url::parse(&p.record.final_url)?;let(title,blocks,mut attachments,warnings)=content(&p.text(),&base)?;if let Some(a)=row.extra["detail_assets"].as_array(){attachments.extend(a.clone())}Ok(GuidelineDoc{source_id:src.id.clone(),doc_key:row.doc_key.clone(),work_key:row.extra["work_key"].as_str().map(String::from),title,url:base.to_string(),item_type:Some("practice_guideline".into()),status:"unknown".into(),rights:common::unknown_rights(),blocks,attachments,fetches:vec![p.record],warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;#[test]fn catalog_and_publisher_gate(){let b=Url::parse("https://www.aan.com/guidelines/home/allguidelines").unwrap();let c=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aan/catalog.html"));assert_eq!(catalog(c,&b).unwrap().len(),1);let p=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aan/page.html"));let(_,blocks,assets,_)=content(p,&b).unwrap();assert!(blocks.iter().any(|x|matches!(&x.kind,BlockKind::Recommendation{strength:Some(s),..} if s=="Level B")));assert_eq!(assets.len(),1);assert!(content("<main><article>Performing security verification</article></main>",&b).is_err());}}
#[cfg(all(test, feature = "guideline-fixtures"))]mod offline_flow{use super::*;#[tokio::test]async fn seeded_discovery_extracts_article(){let dir=tempfile::tempdir().unwrap();let f=Fetcher::new(dir.path(),true,500,1<<20,"").unwrap();let home="https://www.aan.com/practice/guidelines";let list="https://www.aan.com/guidelines/home/allguidelines";let batch="https://www.aan.com/guidelines/home/GetListOfGuidelines?page=0";let empty="https://www.aan.com/guidelines/home/GetListOfGuidelines?page=1";let detail="https://www.aan.com/Guidelines/Home/GuidelineDetail/1158";let article="https://www.aan.com/Guidelines/Home/GetGuidelineContent/1158";f.seed_cache_for_tests(home,b"<html><main><h1>Guidelines</h1><a href='/guidelines/home/allguidelines'>View All</a></main><dialog id='loginDialog'><input type='password'></dialog></html>","text/html");f.seed_cache_for_tests(list,b"<html><main><div id='guideline-list'></div></main><script>var u='/guidelines/home/GetListOfGuidelines?page=';</script></html>","text/html");f.seed_cache_for_tests(batch,include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aan/catalog.html")),"text/html");f.seed_cache_for_tests(empty,b"<ul></ul>","text/html");f.seed_cache_for_tests(detail,b"<html><main><article class='article-details-page'><h1>Example</h1><a href='/Guidelines/Home/GetGuidelineContent/1158'>Read Published Article</a></article></main></html>","text/html");f.seed_cache_for_tests(article,include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/aan/page.html")),"text/html");let src:SourceEntry=serde_json::from_value(json!({"id":"aan","access":"public","enabled":true,"catalog_url":home})).unwrap();let rows=Aan.discover(&src,&f,None).await.unwrap();assert_eq!(rows.len(),1);let doc=Aan.extract(&src,&f,&rows[0]).await.unwrap();assert!(doc.blocks.iter().any(|b|matches!(b.kind,BlockKind::Table{..})));}}
#[cfg(test)]mod gate_tests{use super::*;#[tokio::test]async fn accepts_closed_widget_only_with_public_root(){let dir=tempfile::tempdir().unwrap();let f=Fetcher::new(dir.path(),true,500,1<<20,"").unwrap();let good="https://www.aan.com/good";let open="https://www.aan.com/open";let wall="https://www.aan.com/wall";f.seed_cache_for_tests(good,b"<html><dialog id='loginDialog'><form><input type='password'></form></dialog><main><div id='guideline-list'></div></main><script>/guidelines/home/GetListOfGuidelines?page=</script></html>","text/html");f.seed_cache_for_tests(open,b"<html><dialog id='loginDialog' open><input type='password'></dialog><main><div id='guideline-list'></div></main><script>/guidelines/home/GetListOfGuidelines?page=</script></html>","text/html");f.seed_cache_for_tests(wall,b"<html><main><form action='login'><input type='password'></form></main></html>","text/html");assert!(aan_public(&f,good,"list").await.is_ok());assert!(aan_public(&f,open,"list").await.is_err());assert!(aan_public(&f,wall,"list").await.is_err());}}
